  `always_show` tinyint DEFAULT '0' COMMENT '是否总是显示（0-否，1-是，菜单用）',
  `redirect` varchar(255) DEFAULT NULL COMMENT '重定向地址（菜单用）',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
