  KEY `idx_resource_menu_tree` (`client_code`,`del_flag`,`sort`,`create_time` DESC)
) ENGINE=InnoDB AUTO_INCREMENT=10178 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='系统资源表（菜单/按钮/API）';
