INSERT INTO `ai_crud_config` (`id`, `tenant_id`, `config_key`, `table_name`, `table_comment`, `app_name`, `search_schema`, `columns_schema`, `edit_schema`, `api_config`, `options`, `mode`, `build_mode`, `status`, `publish_status`, `menu_name`, `menu_parent_id`, `menu_sort`, `menu_resource_id`, `dict_config`, `desensitize_config`, `encrypt_config`, `trans_config`, `layout_type`, `model_schema`, `page_schema`, `draft_version`, `published_version`, `publish_time`, `publish_by`, `domain_id`, `domain_code`, `object_code`, `object_name`, `create_by`, `create_time`, `create_dept`, `update_by`, `update_time`, `runtime_datasource_id`, `runtime_datasource_code`, `runtime_datasource_snapshot`, `runtime_table_name`, `primary_key_field`, `primary_key_column`, `primary_key_type`, `tenant_strategy`, `audit_strategy`, `logic_delete_strategy`, `del_flag`, `mount_target`) VALUES (2002,1,'crm_contact','crm_contact','联系人','联系人','[{\"type\": \"input\", \"field\": \"contactName\", \"label\": \"联系人姓名\", \"queryType\": \"like\"}, {\"type\": \"select\", \"field\": \"customerId\", \"label\": \"关联客户\", \"props\": {\"clearable\": true, \"filterable\": true, \"placeholder\": \"请选择关联客户\", \"optionSource\": {\"api\": \"get@/ai/crud/crm_customer/page\", \"type\": \"list\", \"params\": {\"pageNum\": 1, \"pageSize\": 50}, \"keyField\": \"id\", \"labelField\": \"customerName\", \"valueField\": \"id\", \"recordsField\": \"records\", \"fallbackLabelFields\": [\"customerName\", \"name\", \"title\", \"label\", \"customerName\", \"contactName\", \"objectName\"]}, \"labelValueField\": \"customerIdName\"}, \"queryType\": \"eq\", \"optionSource\": {\"api\": \"get@/ai/crud/crm_customer/page\", \"type\": \"list\", \"params\": {\"pageNum\": 1, \"pageSize\": 50}, \"keyField\": \"id\", \"labelField\": \"customerName\", \"valueField\": \"id\", \"recordsField\": \"records\", \"fallbackLabelFields\": [\"customerName\", \"name\", \"title\", \"label\", \"customerName\", \"contactName\", \"objectName\"]}, \"relationLoo