45'),(6,'auth','认证配置','eye','{\"enableApiPermission\":true,\"apiPermissionExcludePaths\":[\"/auth/**\"],\"enableLoginLock\":true,\"maxLoginAttempts\":4,\"lockDuration\":30,\"failRecordExpire\":15,\"sameAccountLoginStrategy\":\"allow_concurrent\",\"enableOnlineUserManagement\":true,\"enableClientValidation\":true,\"enableLegacyClientSecretRead\":true}',4,1,'认证配置','2026-02-25 18:07:35','2026-07-28 11:16:49'),(7,'log','日志配置','eye','{\"enableOperationLog\":true,\"enableLoginLog\":true,\"requestParamsMaxLength\":2000,\"responseResultMaxLength\":2000,\"excludePaths\":[\"/auth/captcha\",\"/actuator/**\",\"/swagger-ui/**\",\"/v3/api-docs/**\"],\"printOperationLog\":true,\"printLoginLog\":true,\"threadPoolCoreSize\":2,\"threadPoolMaxSize\":5,\"threadPoolQueueCapacity\":500}',4,1,'日志配置','2026-02-25 18:07:35','2026-07-03 12:27:17'),(8,'security','安全配置','eye','{\"saToken\":{\"timeout\":2592000,\"activityTimeout\":-1,\"isConcurrent\":true,\"isShare\":false,\"isReadBody\":true,\"isReadHeader\":true,\"isReadCookie\":false,\"tokenPrefix\":\"Bearer\",\"tokenName\":\"Authorization\"},\"passwordPolicy\":{\"minLength\":8,\"requireUppercase\":true,\"requireLowercase\":true,\"requireNumbers\":true,\"requireSpecialChars\":false,\"expireDays\":90,\"historyCount\":5}}',4,1,'安全配置','2026-02-25 18:07:35','2026-09-15 10:59:48');
