uot;:&quot;期望到货日期&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false},{&quot;field&quot;:&quot;status&quot;,&quot;fieldCode&quot;:&quot;status&quot;,&quot;label&quot;:&quot;流程状态&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false},{&quot;field&quot;:&quot;applicantName&quot;,&quot;fieldCode&quot;:&quot;applicantName&quot;,&quot;label&quot;:&quot;申请人&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false},{&quot;field&quot;:&quot;applicantDeptName&quot;,&quot;fieldCode&quot;:&quot;applicantDeptName&quot;,&quot;label&quot;:&quot;申请部门&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false},{&quot;field&quot;:&quot;deptLeaderName&quot;,&quot;fieldCode&quot;:&quot;deptLeaderName&quot;,&quot;label&quot;:&quot;部门负责人&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false},{&quot;field&quot;:&quot;engineeringManagerName&quot;,&quot;fieldCode&quot;:&quot;engineeringManagerName&quot;,&quot;label&quot;:&quot;工程部经理&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false},{&quot;field&quot;:&quot;countersignUserNames&quot;,&quot;fieldCode&quot;:&quot;countersignUserNames&quot;,&quot;label&quot;:&quot;会签人员&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false},{&quot;field&quot;:&quot;arrivalListFileIds&quot;,&quot;fieldCode&quot;:&quot;arrivalListFileIds&quot;,&quot;label&quot;:&quot;上传清单&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false},{&quot;field&quot;:&quot;applicantModifyRemark&quot;,&quot;fieldCode&quot;:&quot;applicantModifyRemark&quot;,&quot;label&quot;:&quot;申请人修改说明&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false},{&quot;field&quot;:&quot;deptLeaderRemark&quot;,&quot;fieldCode&quot;:&quot;deptLeaderRemark&quot;,&quot;label&quot;:&quot;部门负责人意见&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false},{&quot;field&quot;:&quot;engineeringManagerRemark&quot;,&quot;fieldCode&quot;:&quot;engineeringManagerRemark&quot;,&quot;label&quot;:&quot;工程部经理意见&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false},{&quot;field&quot;:&quot;countersignRemark&quot;,&quot;fieldCode&quot;:&quot;countersignRemark&quot;,&quot;label&quot;:&quot;会签意见&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false},{&quot;field&quot;:&quot;rejectReason&quot;,&quot;fieldCode&quot;:&quot;rejectReason&quot;,&quot;label&quot;:&quot;驳回原因&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false},{&quot;field&quot;:&quot;remark&quot;,&quot;fieldCode&quot;:&quot;remark&quot;,&quot;label&quot;:&quot;备注&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false}]\"/>\n    <bpmn:exclusiveGateway id=\"Gateway_dept_result\" name=\"部门负责人审批结果\" default=\"Flow_003\"/>\n    <bpmn:userTask id=\"engineering_manager_approve\" name=\"工程部经理审批\" flowable:assignee=\"${engineeringManagerId}\" flowable:formKey=\"sample_purchase_order_approval_form\" flowable:formFieldPermissions=\"[{&quot;field&quot;:&quot;engineeringManagerRemark&quot;,&quot;fieldCode&quot;:&quot;en